"""SYNTHETIC SUBMISSION — finite EOF exercise, not a persistent protocol."""
def collect_message(recv_chunk, max_bytes=65536):
    chunks = []
    total = 0
    while True:
        chunk = recv_chunk(4)
        if not chunk:
            return b"".join(chunks)
        total += len(chunk)
        if total > max_bytes:
            raise ValueError("maximum size exceeded")
        chunks.append(chunk)
